items.solution:
function findTypeChanges(oldSchema, newSchema) {
  const changes = [];
  for (const field of Object.keys(oldSchema)) {
    if (!(field in newSchema)) continue;
    if (oldSchema[field] !== newSchema[field]) {
      changes.push({ field, from: oldSchema[field], to: newSchema[field] });
    }
  }
  return changes;
}

